# =============================================================================
# Auto-generated by VAE Studio — structural decoder for the VAE-NLME
# engine. Per individual: analytic PK concentrations + (optionally) an ODE for
# further dynamics (e.g. an augmented Neural-ODE), mapped to observations via
# `observe`. ζ = individual parameters (theta), z_lat = latent conditioning.
#
# Speed is the goal: predefined PK models are solved in CLOSED FORM (no ODE);
# remaining ODEs use in-place f! + StaticArrays and are meant to be driven by an
# EnsembleProblem (threaded) across patients. Encoder/ELBO/training are M2.
# =============================================================================
module StructuralDecoder

using OrdinaryDiffEq
const ODE_SILENT = try; DEVerbosity(SciMLLogging.None()); catch; false; end
using DiffEqCallbacks
using ComponentArrays
using ChainRulesCore
using StaticArrays

const PARAM_NAMES = (:MTT, :ka, :V, :Cl)
const LATENT_NAMES = ()
const STATE_NAMES = (:T1, :T2, :T3, :Ad, :Ac)
const N_STATES = 5
const HAS_RATE_DOSE = false
const OBS_NAMES = ("Conc",)
const AI_STATES = ()

# ODE right-hand side. p is a ComponentArray of the differentiable params
# (theta[, latent][, nn]); doses enter via the callback (bolus) — not via p.
function f!(du, u, p, t, dose)
    theta = view(p, 1:4)
    @inbounds begin
        MTT = theta[1]
        ka = theta[2]
        V = theta[3]
        Cl = theta[4]
        T1 = u[1]
        T2 = u[2]
        T3 = u[3]
        Ad = u[4]
        Ac = u[5]
        ktr = 4/MTT
        C = Ac/V
        # dose 'Dose' (bolus) enters T1 via callback
        du[1] = -ktr*T1
        du[2] = ktr*(T1 - T2)
        du[3] = ktr*(T2 - T3)
        du[4] = ktr*T3 - ka*Ad
        du[5] = ka*Ad - Cl/V*Ac
    end
    return nothing
end

function y0(theta)
    MTT = theta[1]
    ka = theta[2]
    V = theta[3]
    Cl = theta[4]
    return vcat(float(0), float(0), float(0), float(0), float(0))
end

function dose_callback(dose, save_pos = (false, false))
    rows = [r for r in axes(dose, 1) if any(!=(0.0), @view dose[r, 2:end])]
    tstops = [dose[r, 1] for r in rows]
    function _affect!(integrator)
        @inbounds for r in rows
            if dose[r, 1] == integrator.t
                integrator.u[1] += dose[r, 2]
            end
        end
    end
    return PresetTimeCallback(tstops, _affect!; save_positions = save_pos)
end

function dose0(dose, t0)
    d0 = zeros(eltype(dose), N_STATES)
    @inbounds for r in axes(dose, 1)
        if dose[r, 1] == t0
            d0[1] += dose[r, 2]
        end
    end
    return d0
end

function solve_one(theta, latent, nn, dose, tspan, saveat;
                   solver = Tsit5(), abstol = 1e-4, reltol = 1e-4,
                   sensealg = nothing)
    p = vcat(theta)
    u0 = y0(theta) .+ (@ignore_derivatives dose0(dose, tspan[1]))
    prob = ODEProblem((du, u, pp, tt) -> f!(du, u, pp, tt, dose), u0, tspan, p)
    ss = tspan[1] == first(saveat)
    cb = @ignore_derivatives dose_callback(dose)
    return solve(prob, solver; verbose = ODE_SILENT, saveat = saveat, callback = cb,
                 abstol = abstol, reltol = reltol, save_start = ss,
                 save_everystep = false, sensealg = sensealg)
end

function f_batch!(du, u, p, t)
    theta = p.theta
    @inbounds begin
        MTT = @view theta[1, :]
        ka = @view theta[2, :]
        V = @view theta[3, :]
        Cl = @view theta[4, :]
        T1 = @view u[1, :]
        T2 = @view u[2, :]
        T3 = @view u[3, :]
        Ad = @view u[4, :]
        Ac = @view u[5, :]
        ktr = @. (4/MTT)
        C = @. (Ac/V)
        @. du[1, :] = (-ktr*T1)
        @. du[2, :] = (ktr*(T1 - T2))
        @. du[3, :] = (ktr*(T2 - T3))
        @. du[4, :] = (ktr*T3 - ka*Ad)
        @. du[5, :] = (ka*Ad - Cl/V*Ac)
    end
    return nothing
end

function y0_batch(theta)
    MTT = @view theta[1, :]
    ka = @view theta[2, :]
    V = @view theta[3, :]
    Cl = @view theta[4, :]
    zc = zero(eltype(theta)) .* @view theta[1, :]   # (N,) Null-Vektor
    i1 = @. (0) + zc
    i2 = @. (0) + zc
    i3 = @. (0) + zc
    i4 = @. (0) + zc
    i5 = @. (0) + zc
    return permutedims(hcat(i1, i2, i3, i4, i5))
end

function dose0_batch(theta, dose, t0)
    d0 = zeros(eltype(theta), N_STATES, size(dose, 1))
    @inbounds for i in axes(dose, 1), r in axes(dose, 2)
        if dose[i, r, 1] == t0
            d0[1, i] += dose[i, r, 2]
        end
    end
    return d0
end

function dose_callback_batch(dose)
    ev = Tuple{Float64, Int, Int}[]
    @inbounds for i in axes(dose, 1), r in axes(dose, 2)
        any(!=(0.0), @view dose[i, r, 2:end]) && push!(ev, (dose[i, r, 1], i, r))
    end
    tstops = unique(first.(ev))
    function _affect!(integrator)
        @inbounds for (te, i, r) in ev
            if te == integrator.t
                integrator.u[1, i] += dose[i, r, 2]
            end
        end
    end
    return PresetTimeCallback(tstops, _affect!; save_positions = (false, false))
end

function solve_batch(theta, dose, tspan, saveat;
                     solver = Tsit5(), abstol = 1e-4, reltol = 1e-4)
    p = ComponentArray(theta = theta)
    u0 = y0_batch(theta) .+ dose0_batch(theta, dose, tspan[1])
    prob = ODEProblem(f_batch!, u0, tspan, p)
    ss = tspan[1] == first(saveat)
    cb = dose_callback_batch(dose)
    return solve(prob, solver; verbose = ODE_SILENT, saveat = saveat, callback = cb,
                 abstol = abstol, reltol = reltol, save_start = ss,
                 save_everystep = false)
end

# observe_batch: u (N_STATES, N), theta (n_params, N) at time t -> (N, ktypes)
function observe_batch(u, theta, t)
    @inbounds begin
        MTT = @view theta[1, :]
        ka = @view theta[2, :]
        V = @view theta[3, :]
        Cl = @view theta[4, :]
        T1 = @view u[1, :]
        T2 = @view u[2, :]
        T3 = @view u[3, :]
        Ad = @view u[4, :]
        Ac = @view u[5, :]
        ktr = @. (4/MTT)
        C = @. (Ac/V)
        out = similar(u, size(u, 2), 1)
        @. out[:, 1] = (C)
        return out
    end
end

# Predicted observations at (u, t) in OBS_NAMES order. p = (theta, latent, ..).
function observe(u, p, t)
    theta = p.theta; latent = p.latent; dose = p.dose
    @inbounds begin
        MTT = theta[1]
        ka = theta[2]
        V = theta[3]
        Cl = theta[4]
        T1 = u[1]
        T2 = u[2]
        T3 = u[3]
        Ad = u[4]
        Ac = u[5]
        ktr = 4/MTT
        C = Ac/V
        return (C,)
    end
end

const OBSF_NP = 4
function obsf(u, p, t, dose)
    theta = view(p, 1:4)
    @inbounds begin
        MTT = theta[1]
        ka = theta[2]
        V = theta[3]
        Cl = theta[4]
        T1 = u[1]
        T2 = u[2]
        T3 = u[3]
        Ad = u[4]
        Ac = u[5]
        ktr = 4/MTT
        C = Ac/V
        return SVector(C)
    end
end

const ALLVAR_NAMES = ("T1", "T2", "T3", "Ad", "Ac", "ktr", "C")
# Every model quantity at (u, t) in ALLVAR_NAMES order — for the results plots.
function allvars(u, p, t)
    theta = p.theta; latent = p.latent; dose = p.dose
    @inbounds begin
        MTT = theta[1]
        ka = theta[2]
        V = theta[3]
        Cl = theta[4]
        T1 = u[1]
        T2 = u[2]
        T3 = u[3]
        Ad = u[4]
        Ac = u[5]
        ktr = 4/MTT
        C = Ac/V
        return (T1, T2, T3, Ad, Ac, ktr, C)
    end
end

# Predict observations at `times` for one individual.
function predict(theta, latent, nn, dose, times)
    p = (theta = theta, latent = latent, nn = nn, dose = dose)
    tspan = (first(times), last(times))
    sol = solve_one(theta, latent, nn, dose, tspan, times)
    return [observe(sol.u[j], p, times[j]) for j in eachindex(times)]
end

end # module StructuralDecoder
